/**
 * 根据 replace_models 查找替代服务器（入口，递归深度从 0 开始）
 *
 * @param replaceModelsJson replace_models 字段的 JSON 字符串
 * @return 状态正常的最优替代服务器，找不到返回 null
 */
public ConfServerListTab findReplaceServer(String replaceModelsJson) {
    return findReplaceServer(replaceModelsJson, 0);
}

/**
 * 从按字段精确匹配出的记录中选可用替代：
 * 1. 优先返回状态正常的第一条记录
 * 2. 若全部状态异常，则沿每条记录的 replace_models 链递归向上查找（深度上限 MAX_REPLACE_DEPTH）
 *
 * @param rows 字段精确匹配出的记录（未过滤状态，delete_flag=0）
 * @param matchedBy 命中来源描述（日志用）
 * @param depth 当前递归深度
 * @return 状态正常的替代服务器，找不到返回 null
 */
private ConfServerListTab pickOrFollowChain(List<ConfServerListTab> rows, String matchedBy, int depth) {
    if (CollectionUtils.isEmpty(rows)) {
        return null;
    }
    for (ConfServerListTab server : rows) {
        if (BAD_PRODUCT_STATUSES.contains(server.getProductStatus())) {
            continue;
        }
        return server;
    }
    // 全部状态异常，沿每条记录的 replace_models 链递归向上查找
    for (ConfServerListTab server : rows) {
        ConfServerListTab chain = followChain(server, depth);
        if (chain != null) {
            return chain;
        }
    }
    return null;
}
